const out = {};
async function info(id, name) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out[name] = 'NOT FOUND'; return; }
  const o = { type: n.type, w: Math.round(n.width*10)/10, h: Math.round(n.height*10)/10 };
  if (n.type === 'COMPONENT' || n.type === 'INSTANCE') {
    try { o.props = Object.keys(n.componentPropertyDefinitions || {}); } catch(e) { o.props = 'n/a'; }
  }
  if ('fills' in n && Array.isArray(n.fills)) o.fills = JSON.stringify(n.fills.map(f => f.type === 'SOLID' ? {t:'S', c:f.color} : {t:f.type})).slice(0, 400);
  if (n.children && n.children.length <= 8) {
    o.kids = n.children.map(c => {
      const k = { t: c.type, n: c.name, w: Math.round(c.width*10)/10, h: Math.round(c.height*10)/10 };
      if ('fills' in c && Array.isArray(c.fills)) k.f = JSON.stringify(c.fills.map(f => f.type === 'SOLID' ? {t:'S', c:{r:Math.round(f.color.r*255), g:Math.round(f.color.g*255), b:Math.round(f.color.b*255)}} : {t:f.type})).slice(0, 200);
      if (c.type === 'TEXT') { k.chars = c.characters.slice(0, 40); k.fs = c.fontSize; k.ff = c.fontName && c.fontName.style; }
      return k;
    });
  }
  out[name] = o;
}
